package soulflameaudio;

/** How the remaining Entice time is counted down on screen. */
public enum CountdownUnit
{
	SECONDS("Seconds", "s"),
	TICKS("Ticks", "t");

	private final String label;
	private final String suffix;

	CountdownUnit(String label, String suffix)
	{
		this.label = label;
		this.suffix = suffix;
	}

	String getSuffix()
	{
		return suffix;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package soulflameaudio;

/** Everything that can happen around an Entice buff, from the point of view of one player. */
public enum EnticeStatus
{
	/** We blew the horn and it reached at least one ally. */
	SENT,
	/** An ally's horn buffed us. */
	RECEIVED,
	/** We spent the buff on a hit. */
	SPENT,
	/** We blew the horn with nobody in range to hear it. */
	MISSED,
	/** We let the buff expire unused. */
	WASTED
}

package soulflameaudio;

import lombok.Data;
import lombok.EqualsAndHashCode;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Broadcast by the player who received an Entice buff, naming whoever gave it to them so only that
 * player reacts. The sender's own identity arrives separately via {@link #getMemberId()}.
 */
@Data
@EqualsAndHashCode(callSuper = true)
public class EnticeStatusMessage extends PartyMemberMessage
{
	private EnticeStatus status;
	private String casterName;

	/** The sender's own choice of overhead line for this status, or null to show nothing. */
	private String overheadText;

	public EnticeStatusMessage()
	{
	}

	public EnticeStatusMessage(EnticeStatus status, String casterName, String overheadText)
	{
		this.status = status;
		this.casterName = casterName;
		this.overheadText = overheadText;
	}
}

package soulflameaudio;

import lombok.Data;
import lombok.EqualsAndHashCode;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Broadcast whenever the sender's horn radius changes, so the party can draw it around them. Only
 * the sender's own client can read the radius they set, which is why it has to travel this way.
 */
@Data
@EqualsAndHashCode(callSuper = true)
public class HornRadiusMessage extends PartyMemberMessage
{
	/** In tiles, or zero while the horn is not worn, not configured, or not shared. */
	private int radius;

	public HornRadiusMessage()
	{
	}

	public HornRadiusMessage(int radius)
	{
		this.radius = radius;
	}
}

package soulflameaudio;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(SoulflameHornAudioConfig.GROUP)
public interface SoulflameHornAudioConfig extends Config
{
	String GROUP = "soulflamehornaudio";
	String RADIUS_COLOUR = "radiusMarkerColour";
	String RADIUS_FILL_OPACITY = "radiusFillOpacity";

	// The same for every sound's file setting
	String FILE_DESCRIPTION = "Leave blank for the default sound. Otherwise the full path to a .wav file, or to a folder to play one at random. "
		+ "A file name on its own is looked for in .runelite\\soulflamehornaudio.";

	@ConfigSection(
		name = "General",
		description = "Sound playback and which moments make a noise.",
		position = 0
	)
	String soundsSection = "sounds";

	@ConfigSection(
		name = "Custom Audio",
		description = "Play your own files instead of the bundled tones.",
		position = 2,
		closedByDefault = true
	)
	String customSection = "custom";

	@ConfigSection(
		name = "Overlay",
		description = "On-screen readouts for your own Entice buff.",
		position = 1
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Overhead Text",
		description = "Lines shown above players' heads. Always client side, so nobody outside the plugin sees them.",
		position = 3
	)
	String overheadSection = "overhead";

	@ConfigSection(
		name = "Party",
		description = "Share your horn events with your RuneLite party. Everyone involved needs this plugin.",
		position = 4,
		closedByDefault = true
	)
	String partySection = "party";

	// General

	@ConfigItem(
		keyName = "enableSounds",
		name = "Enable Sounds",
		description = "Master switch for all audio. Turn off to rely on the overhead text alone. The individual sounds below are ignored while this is off.",
		section = soundsSection,
		position = 0
	)
	default boolean enableSounds()
	{
		return true;
	}

	@ConfigItem(
		keyName = "volume",
		name = "Volume",
		description = "Playback volume as a percentage.",
		section = soundsSection,
		position = 1
	)
	@Range(max = 200)
	default int volume()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "playSentSound",
		name = "Player Sent Spec",
		description = "Play a sound when you blow the horn and it reaches at least one ally.",
		section = soundsSection,
		position = 2
	)
	default boolean playSentSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playAppliedSound",
		name = "Player Received Spec",
		description = "Play a sound when the Entice buff lands on you, whether you blew the horn or an ally did.",
		section = soundsSection,
		position = 3
	)
	default boolean playAppliedSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playConsumedSound",
		name = "Player Utilized Spec",
		description = "Play a sound when you cash the buff in on a hit.",
		section = soundsSection,
		position = 4
	)
	default boolean playConsumedSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playWhiffSound",
		name = "Player Missed Spec",
		description = "Play a sound when you blow the horn with nobody in range to hear it.",
		section = soundsSection,
		position = 5
	)
	default boolean playWhiffSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playFadedSound",
		name = "Player Wasted Spec",
		description = "Play a sound when your buff expires unused.",
		section = soundsSection,
		position = 6
	)
	default boolean playFadedSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "playAllyWastedSound",
		name = "Party Wasted Spec",
		description = "Play a sound when a party member wastes a buff you gave them. Needs the party settings.",
		section = soundsSection,
		position = 7
	)
	default boolean playAllyWastedSound()
	{
		return true;
	}

	// Custom Audio

	@ConfigItem(
		keyName = "useCustomSounds",
		name = "Use Custom Audio",
		description = "Play your own files instead of the bundled tones. Supports .wav, .au and .aiff; mp3 and ogg cannot be played. The fields below only take effect while this is on.",
		section = customSection,
		position = 0
	)
	default boolean useCustomSounds()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sentFile",
		name = "Player Sent Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 1
	)
	default String sentFile()
	{
		return "";
	}

	@ConfigItem(
		keyName = "appliedFile",
		name = "Player Received Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 2
	)
	default String appliedFile()
	{
		return "";
	}

	@ConfigItem(
		keyName = "consumedFile",
		name = "Player Utilized Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 3
	)
	default String consumedFile()
	{
		return "";
	}

	@ConfigItem(
		keyName = "whiffFile",
		name = "Player Missed Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 4
	)
	default String whiffFile()
	{
		return "";
	}

	@ConfigItem(
		keyName = "fadedFile",
		name = "Player Wasted Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 5
	)
	default String fadedFile()
	{
		return "";
	}

	@ConfigItem(
		keyName = "allyWastedFile",
		name = "Party Wasted Spec File",
		description = FILE_DESCRIPTION,
		section = customSection,
		position = 6
	)
	default String allyWastedFile()
	{
		return "";
	}

	// Overlay

	@ConfigItem(
		keyName = "showInfobox",
		name = "Display Buff Infobox",
		description = "Show the horn's icon with a countdown while your Entice buff is active.",
		section = overlaySection,
		position = 0
	)
	default boolean showInfobox()
	{
		return true;
	}

	@ConfigItem(
		keyName = "countdownUnit",
		name = "Countdown Units",
		description = "Count the remaining buff down in seconds or in game ticks. Ten ticks is six seconds.",
		section = overlaySection,
		position = 1
	)
	default CountdownUnit countdownUnit()
	{
		return CountdownUnit.SECONDS;
	}

	@ConfigItem(
		keyName = "showHornRadius",
		name = "Draw Horn Radius",
		description = "Outline the ground your horn reaches while it is equipped, so you can see who is inside it. Follows the radius you set on the horn itself.",
		section = overlaySection,
		position = 2
	)
	default boolean showHornRadius()
	{
		return false;
	}

	@ConfigItem(
		keyName = RADIUS_COLOUR,
		name = "Radius Colour",
		description = "Colour of the horn radius. Its opacity fades the outline and the fill together.",
		section = overlaySection,
		position = 3
	)
	@Alpha
	default Color radiusColour()
	{
		return new Color(0, 255, 0);
	}

	@ConfigItem(
		keyName = RADIUS_FILL_OPACITY,
		name = "Radius Fill Opacity",
		description = "How strongly the area is shaded, as a share of the radius colour's opacity.",
		section = overlaySection,
		position = 4
	)
	@Range(max = 100)
	@Units(Units.PERCENT)
	default int radiusFillOpacity()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "radiusBorderWidth",
		name = "Radius Border Width",
		description = "Width of the horn radius outline.",
		section = overlaySection,
		position = 5
	)
	default double radiusBorderWidth()
	{
		return 2;
	}

	// Overhead Text

	@ConfigItem(
		keyName = "showOwnOverheadText",
		name = "Draw Above Self",
		description = "Show your own lines above your own head. Works alone, no party needed.",
		section = overheadSection,
		position = 0
	)
	default boolean showOwnOverheadText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showAllyOverheadText",
		name = "Draw Above Party Members",
		description = "Show lines above party members' heads as they are buffed, spend it and waste it. Needs the party settings.",
		section = overheadSection,
		position = 1
	)
	default boolean showAllyOverheadText()
	{
		return true;
	}

	@ConfigItem(
		keyName = "useOthersDialogue",
		name = "Use Their Dialogue",
		description = "Show each party member's own wording above their head instead of yours. Off by default, so everything you see is what you configured here.",
		section = overheadSection,
		position = 2
	)
	default boolean useOthersDialogue()
	{
		return false;
	}

	@ConfigItem(
		keyName = "sentOverheadText",
		name = "Player Sent Spec",
		description = "Line shown when someone blows the horn and it reaches an ally. Leave blank for none.",
		section = overheadSection,
		position = 3
	)
	default String sentOverheadText()
	{
		return "Horn up!";
	}
	@ConfigItem(
		keyName = "appliedOverheadText",
		name = "Player Received Spec",
		description = "Line shown when the Entice buff lands on someone. Leave blank for none.",
		section = overheadSection,
		position = 4
	)
	default String appliedOverheadText()
	{
		return "Buffed!";
	}

	@ConfigItem(
		keyName = "spentOverheadText",
		name = "Player Utilized Spec",
		description = "Line shown when the buff is cashed in on a hit. Leave blank for none.",
		section = overheadSection,
		position = 5
	)
	default String spentOverheadText()
	{
		return "Used it!";
	}

	@ConfigItem(
		keyName = "whiffOverheadText",
		name = "Player Missed Spec",
		description = "Line shown when the horn is blown with nobody in range. Leave blank for none.",
		section = overheadSection,
		position = 6
	)
	default String whiffOverheadText()
	{
		return "Nobody heard that...";
	}

	@ConfigItem(
		keyName = "wastedOverheadText",
		name = "Player Wasted Spec",
		description = "Line shown when the buff expires unused. Leave blank for none.",
		section = overheadSection,
		position = 7
	)
	default String wastedOverheadText()
	{
		return "I wasted it!";
	}

	@ConfigItem(
		keyName = "partyWastedOverheadText",
		name = "Party Wasted Spec",
		description = "Line shown above a party member who wasted a buff you gave them. Leave blank for none.",
		section = overheadSection,
		position = 8
	)
	default String partyWastedOverheadText()
	{
		return "Wasted your buff!";
	}

	// Party

	@ConfigItem(
		keyName = "partyIntegration",
		name = "Share With Party",
		description = "Broadcast your horn events to your RuneLite party, and react to theirs. Everyone involved needs this plugin and the same party.",
		section = partySection,
		position = 0
	)
	default boolean partyIntegration()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPartyRadius",
		name = "Draw Party Radius",
		description = "Outline the ground a party member's horn reaches while they wear it, using the radius they set. They need this plugin with Share With Party on.",
		section = partySection,
		position = 1
	)
	default boolean showPartyRadius()
	{
		return true;
	}

	@ConfigItem(
		keyName = "partyRadiusColour",
		name = "Party Radius Colour",
		description = "Colour of party members' horn radius. Its opacity fades the outline and the fill together, which take their fill opacity and border width from your own radius.",
		section = partySection,
		position = 2
	)
	@Alpha
	default Color partyRadiusColour()
	{
		return new Color(0, 200, 255);
	}

}

package soulflameaudio;

import com.google.inject.Provides;
import java.awt.Color;
import java.io.File;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import java.util.regex.Pattern;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.RuneLite;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Soulflame Horn",
	description = "Sounds, overhead text and a radius overlay for the Soulflame horn's Entice special attack",
	tags = {"soulflame", "horn", "yama", "entice", "sound", "audio", "special", "overlay"}
)
public class SoulflameHornAudioPlugin extends Plugin
{
	static final String SENT_SOUND = "entice-sent";
	static final String APPLIED_SOUND = "entice-applied";
	static final String CONSUMED_SOUND = "entice-consumed";
	static final String WHIFF_SOUND = "entice-whiff";
	static final String FADED_SOUND = "entice-faded";
	static final String ALLY_WASTED_SOUND = "entice-ally-wasted";
	static final File SOUND_DIR = new File(RuneLite.RUNELITE_DIR, SoulflameHornAudioConfig.GROUP);

	private static final String BUNDLED_SOUND_PATH = "/soulflameaudio/";
	private static final String WAV = ".wav";

	/** Everything java.sound can decode without a third party library. Notably not mp3 or ogg. */
	private static final String[] AUDIO_EXTENSIONS = {".wav", ".au", ".aif", ".aiff"};

	/**
	 * Entice empowers the next melee attack made within 10 ticks. The server announces the expiry
	 * itself, so this only exists to drop stale state if that message is ever missed.
	 */
	private static final int ENTICE_DURATION_TICKS = 10;

	/** A game tick is 600ms, used to turn the tick counter into seconds for display. */
	private static final int MILLIS_PER_TICK = 600;

	// Compared against the lowercased game message. The ally variant is prefixed with their name.
	private static final String SELF_CAST = "you encourage nearby allies";
	private static final String ALLY_CAST = "encourages you with their soulflame horn";
	private static final String NO_LISTENERS = "you blow your horn into the wind";
	private static final String EFFECT_FADED = "soulflame horn's effect fades away";

	/** Splits "<name> encourages you with their soulflame horn." to recover the caster. */
	private static final String ALLY_CAST_NAME_SUFFIX = " encourages you with";
	/**
	 * The game can colour the caster's name with a code such as {@code @mes_hl_blu@}, which
	 * {@link Text#removeTags} leaves in place. Player names cannot contain {@code @}.
	 */
	private static final Pattern COLOUR_CODE = Pattern.compile("@[a-z0-9_]+@");

	/** Where the radius colour was saved before its opacity covered the outline too. */
	private static final String LEGACY_RADIUS_COLOUR = "radiusColour";

	/** Roughly two seconds of overhead text, matching how long the game shows its own. */
	private static final int OVERHEAD_CYCLES = 120;

	/** Overhead text comes from another player's config, so it does not get to be arbitrarily long. */
	private static final int MAX_OVERHEAD_CHARS = 80;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private SoulflameHornAudioConfig config;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	@Inject
	private ItemManager itemManager;

	@Inject
	private InfoBoxManager infoBoxManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SoulflameHornRadiusOverlay radiusOverlay;

	@Inject
	private SoulflameHornReminderOverlay reminderOverlay;

	private SoulflameHornInfoBox infoBox;

	private int enticeTicksRemaining;

	/** Who gave us the current buff, or null when we blew the horn ourselves. */
	private String enticeCaster;

	/** The tick the current buff was given, so only attacks made since then say how it was used. */
	private int enticeCastTick;

	/** A hit of ours that may have spent the buff, decided at the end of its tick. See {@link #onGameTick}. */
	private boolean hitPending;
	private int hitTick;

	/**
	 * A wasted horn can fade for several people at once, us and every party member it reached. Only the
	 * first of those plays a sound, so one blow never makes more than one noise when it goes to waste.
	 */
	private boolean expirySoundPlayed;

	/** The horn radius each party member has shared, by member id, for those wearing a configured horn. */
	private final Map<Long, Integer> partyRadii = new HashMap<>();

	/** The radius we last shared with the party, zero meaning none, which is also what a new party assumes. */
	private int sharedRadius;

	/** Last seen experience per skill, to tell a gain from the values the client reports on login. */
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);

	/** The latest tick the player gained melee experience, and ranged or magic experience. */
	private int lastMeleeXpTick = -1;
	private int lastRangedOrMagicXpTick = -1;

	@Provides
	SoulflameHornAudioConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SoulflameHornAudioConfig.class);
	}

	@Override
	protected void startUp()
	{
		enticeTicksRemaining = 0;
		enticeCaster = null;
		hitPending = false;
		lastXp.clear();
		migrateRadiusColour();
		partyRadii.clear();
		sharedRadius = 0;
		wsClient.registerMessage(EnticeStatusMessage.class);
		wsClient.registerMessage(HornRadiusMessage.class);
		overlayManager.add(radiusOverlay);
		overlayManager.add(reminderOverlay);

		infoBox = new SoulflameHornInfoBox(itemManager.getImage(ItemID.SOULFLAME_HORN), this, this);
		infoBoxManager.addInfoBox(infoBox);

		if (!SOUND_DIR.exists() && !SOUND_DIR.mkdirs())
		{
			log.warn("Could not create sound override directory {}", SOUND_DIR);
		}
	}

	/**
	 * The radius colour's opacity once shaded only the area, with the outline always solid. It now
	 * fades both, so a colour saved the old way moves to the new setting at full opacity, and its old
	 * opacity becomes the fill's share, which draws it just as before.
	 */
	void migrateRadiusColour()
	{
		final Color old = configManager.getConfiguration(SoulflameHornAudioConfig.GROUP, LEGACY_RADIUS_COLOUR, Color.class);
		if (old == null)
		{
			return;
		}

		configManager.setConfiguration(SoulflameHornAudioConfig.GROUP, SoulflameHornAudioConfig.RADIUS_COLOUR,
			new Color(old.getRed(), old.getGreen(), old.getBlue()));
		configManager.setConfiguration(SoulflameHornAudioConfig.GROUP, SoulflameHornAudioConfig.RADIUS_FILL_OPACITY,
			Math.round(old.getAlpha() * 100f / 255));
		configManager.unsetConfiguration(SoulflameHornAudioConfig.GROUP, LEGACY_RADIUS_COLOUR);
	}

	@Override
	protected void shutDown()
	{
		enticeTicksRemaining = 0;
		enticeCaster = null;
		wsClient.unregisterMessage(EnticeStatusMessage.class);
		wsClient.unregisterMessage(HornRadiusMessage.class);
		partyRadii.clear();
		overlayManager.remove(radiusOverlay);
		overlayManager.remove(reminderOverlay);
		infoBoxManager.removeInfoBox(infoBox);
		infoBox = null;
	}

	boolean isEnticeActive()
	{
		return enticeTicksRemaining > 0;
	}

	boolean isInfoBoxEnabled()
	{
		return config.showInfobox();
	}

	/** Rounded up, so a buff with any time left never reads as zero seconds. */
	int getEnticeSecondsRemaining()
	{
		return (enticeTicksRemaining * MILLIS_PER_TICK + 999) / 1000;
	}

	/** The bare number for the infobox, in whichever unit is configured. */
	String getEnticeCountdown()
	{
		return Integer.toString(config.countdownUnit() == CountdownUnit.TICKS
			? enticeTicksRemaining
			: getEnticeSecondsRemaining());
	}

	/** The radius in tiles, or zero while the horn has never been configured. */
	int getHornRadius()
	{
		return client.getVarbitValue(VarbitID.YAMA_HORN_RADIUS);
	}

	/**
	 * The horn reports no radius until it has been configured, and the configure option only appears
	 * while it is equipped. Distinguishing that from a real radius is what lets the reminder explain
	 * an otherwise blank overlay.
	 */
	boolean isHornRadiusConfigured()
	{
		return getHornRadius() > 0;
	}

	/**
	 * Read from the equipment container rather than a varbit, so this reflects what is actually worn
	 * rather than relying on the meaning of a varbit name.
	 */
	boolean isHornEquipped()
	{
		final ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return false;
		}

		final Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		return weapon != null && weapon.getId() == ItemID.SOULFLAME_HORN;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		final String message = event.getMessage().toLowerCase();

		if (message.contains(SELF_CAST) || message.contains(ALLY_CAST))
		{
			final boolean ourOwnHorn = !message.contains(ALLY_CAST);

			enticeTicksRemaining = ENTICE_DURATION_TICKS;
			enticeCaster = ourOwnHorn ? null : casterFrom(event.getMessage());
			enticeCastTick = client.getTickCount();
			hitPending = false;
			expirySoundPlayed = false;
			log.debug("Entice applied by {}, expires in {} ticks",
				ourOwnHorn ? "self" : enticeCaster, ENTICE_DURATION_TICKS);

			// Blowing your own horn buffs you as well, but only one of the two events should fire.
			if (ourOwnHorn)
			{
				announce(EnticeStatus.SENT, config.sentOverheadText());

				if (config.playSentSound())
				{
					play(SENT_SOUND, config.sentFile());
				}
			}
			else
			{
				announce(EnticeStatus.RECEIVED, config.appliedOverheadText());

				if (config.playAppliedSound())
				{
					play(APPLIED_SOUND, config.appliedFile());
				}
			}
		}
		else if (message.contains(EFFECT_FADED))
		{
			// The server only sends this when the buff went unused, so it needs no state of its own.
			enticeTicksRemaining = 0;
			log.debug("Entice wasted");

			announce(EnticeStatus.WASTED, config.wastedOverheadText());
			enticeCaster = null;

			if (config.playFadedSound())
			{
				playExpiry(FADED_SOUND, config.fadedFile());
			}
		}
		else if (message.contains(NO_LISTENERS))
		{
			announce(EnticeStatus.MISSED, config.whiffOverheadText());

			if (config.playWhiffSound())
			{
				play(WHIFF_SOUND, config.whiffFile());
			}
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (enticeTicksRemaining <= 0)
		{
			return;
		}

		// Damage we dealt to something else. Damage we take carries the same "mine" tint, hence the actor check.
		final Hitsplat hitsplat = event.getHitsplat();
		if (!hitsplat.isMine() || event.getActor() == client.getLocalPlayer())
		{
			return;
		}

		hitPending = true;
		hitTick = client.getTickCount();
	}

	/**
	 * Experience lands when an attack is made, so it shows which style the player is attacking with.
	 * Melee trains Attack, Strength or Defence. Ranged and magic train their own skill, and their
	 * defensive styles add Defence alongside it.
	 */
	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		final Integer previous = lastXp.put(event.getSkill(), event.getXp());
		if (previous == null || event.getXp() <= previous)
		{
			return;
		}

		switch (event.getSkill())
		{
			case ATTACK:
			case STRENGTH:
			case DEFENCE:
				lastMeleeXpTick = client.getTickCount();
				break;
			case RANGED:
			case MAGIC:
				lastRangedOrMagicXpTick = client.getTickCount();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Before the countdown, so a hit on the buff's last tick still counts.
		if (hitPending)
		{
			hitPending = false;
			if (enticeTicksRemaining > 0 && hitWasMelee())
			{
				spend();
			}
		}

		if (enticeTicksRemaining > 0)
		{
			enticeTicksRemaining--;
		}

		shareRadius();
	}

	/**
	 * Tells the party our horn's radius whenever it changes, and zero once the horn comes off. With
	 * sharing turned off, a radius already shared is withdrawn and nothing more is sent.
	 */
	private void shareRadius()
	{
		if (!partyService.isInParty())
		{
			return;
		}

		final int radius = config.partyIntegration() && isHornEquipped() ? getHornRadius() : 0;
		if (radius != sharedRadius)
		{
			sharedRadius = radius;
			partyService.send(new HornRadiusMessage(radius));
		}
	}

	@Subscribe
	public void onHornRadiusMessage(HornRadiusMessage event)
	{
		clientThread.invokeLater(() ->
		{
			final PartyMember local = partyService.getLocalMember();
			if (local != null && event.getMemberId() == local.getMemberId())
			{
				return;
			}

			if (event.getRadius() > 0)
			{
				partyRadii.put(event.getMemberId(), event.getRadius());
			}
			else
			{
				partyRadii.remove(event.getMemberId());
			}
		});
	}

	/** Someone new knows nothing of our horn, so it is shared again on the next tick. */
	@Subscribe
	public void onUserJoin(UserJoin event)
	{
		clientThread.invokeLater(() -> sharedRadius = 0);
	}

	@Subscribe
	public void onUserPart(UserPart event)
	{
		clientThread.invokeLater(() -> partyRadii.remove(event.getMemberId()));
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		clientThread.invokeLater(() ->
		{
			partyRadii.clear();
			sharedRadius = 0;
		});
	}

	/** The party members on screen wearing a configured horn, with the radius each of them set. */
	Map<Player, Integer> partyHornRadii()
	{
		final Map<Player, Integer> shown = new HashMap<>();
		for (Map.Entry<Long, Integer> entry : partyRadii.entrySet())
		{
			final PartyMember member = partyService.getMemberById(entry.getKey());
			final Player player = member == null ? null : findPlayer(member.getDisplayName());
			if (player != null)
			{
				shown.put(player, entry.getValue());
			}
		}
		return shown;
	}

	/**
	 * Entice only empowers melee, so a ranged or magic hit leaves it waiting for the next melee one.
	 * A hit counts when melee experience landed with it, or the tick before, no earlier than the horn,
	 * and is the latest combat experience. A tie means Defence came with Ranged or Magic, from longrange
	 * or defensive casting. A hit with no experience at all is not taken as melee: thralls deal damage
	 * that is ours but gives none. A melee hit of 0, or at 200m experience, gives none either, so it
	 * goes unannounced rather than a thrall spending the buff.
	 */
	private boolean hitWasMelee()
	{
		return lastMeleeXpTick >= enticeCastTick
			&& lastMeleeXpTick >= hitTick - 1
			&& lastMeleeXpTick > lastRangedOrMagicXpTick;
	}

	private void spend()
	{
		enticeTicksRemaining = 0;
		log.debug("Entice spent");

		announce(EnticeStatus.SPENT, config.spentOverheadText());
		enticeCaster = null;

		if (config.playConsumedSound())
		{
			play(CONSUMED_SOUND, config.consumedFile());
		}
	}

	/** Shows our own line locally and, when in a party, tells everyone else so they can show it too. */
	private void announce(EnticeStatus status, String overheadText)
	{
		if (config.showOwnOverheadText())
		{
			showOverheadTextOn(client.getLocalPlayer(), overheadText);
		}

		if (!config.partyIntegration() || !partyService.isInParty())
		{
			return;
		}

		// a miss is our own horn, even while we hold someone else's buff
		final String caster = status == EnticeStatus.MISSED ? null : enticeCaster;
		partyService.send(new EnticeStatusMessage(status, caster, overheadText));
	}

	@Subscribe
	public void onEnticeStatusMessage(EnticeStatusMessage event)
	{
		// Party messages arrive on the network thread. Handled on the client thread like everything
		// else, a report never races our own fade to the one wasted sound, and reads the game safely.
		clientThread.invokeLater(() -> handleReport(event));
	}

	private void handleReport(EnticeStatusMessage event)
	{
		if (!config.partyIntegration() || event.getMemberId() == partyService.getLocalMember().getMemberId())
		{
			return;
		}

		final PartyMember sender = partyService.getMemberById(event.getMemberId());
		final String senderName = sender == null ? null : sender.getDisplayName();
		log.debug("{} reports {}", senderName, event.getStatus());

		// The sound is about our own buff going to waste, so it only fires for the player who cast it.
		// The text is shown to the whole party, including others who were buffed by the same horn.
		final boolean ours = weCast(event);
		if (event.getStatus() == EnticeStatus.WASTED && config.playAllyWastedSound() && ours)
		{
			playExpiry(ALLY_WASTED_SOUND, config.allyWastedFile());
		}

		if (config.showAllyOverheadText() && senderName != null)
		{
			showOverheadText(senderName, textFor(event, ours));
		}
	}

	/**
	 * Our own wording by default, so what appears on screen is what this client configured. Their
	 * wording is only used when we opt in, and even then ours covers anything they left blank.
	 */
	private String textFor(EnticeStatusMessage event, boolean weCast)
	{
		if (config.useOthersDialogue())
		{
			final String theirs = sanitizeOverheadText(event.getOverheadText());
			if (theirs != null)
			{
				return theirs;
			}
		}

		// Somebody squandering a buff we handed them is its own moment, so it gets its own line.
		if (weCast && event.getStatus() == EnticeStatus.WASTED)
		{
			return config.partyWastedOverheadText();
		}

		return ourTextFor(event.getStatus());
	}

	private String ourTextFor(EnticeStatus status)
	{
		switch (status)
		{
			case SENT:
				return config.sentOverheadText();
			case MISSED:
				return config.whiffOverheadText();
			case RECEIVED:
				return config.appliedOverheadText();
			case SPENT:
				return config.spentOverheadText();
			case WASTED:
				return config.wastedOverheadText();
			default:
				return null;
		}
	}

	private boolean weCast(EnticeStatusMessage event)
	{
		final Player localPlayer = client.getLocalPlayer();
		return localPlayer != null
			&& localPlayer.getName() != null
			&& event.getCasterName() != null
			// plain on both sides, as a client on an older version sends the name with its colour code
			&& plainName(localPlayer.getName()).equalsIgnoreCase(plainName(event.getCasterName()));
	}

	private static String plainName(String name)
	{
		return Text.sanitize(COLOUR_CODE.matcher(name).replaceAll("")).trim();
	}

	/**
	 * The sender picks this text, so strip anything that could misrender on our screen and cap the
	 * length rather than trusting another client's config verbatim.
	 */
	private static String sanitizeOverheadText(String text)
	{
		if (text == null)
		{
			return null;
		}

		final String plain = Text.removeTags(text).trim();
		if (plain.isEmpty())
		{
			return null;
		}

		return plain.length() > MAX_OVERHEAD_CHARS ? plain.substring(0, MAX_OVERHEAD_CHARS) : plain;
	}

	/** Client side only, so the text appears above that player for us and nobody else. */
	private void showOverheadText(String playerName, String text)
	{
		showOverheadTextOn(findPlayer(playerName), text);
	}

	private Player findPlayer(String name)
	{
		if (name == null)
		{
			return null;
		}

		final String wanted = plainName(name);
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player.getName() != null && plainName(player.getName()).equalsIgnoreCase(wanted))
			{
				return player;
			}
		}
		return null;
	}

	private void showOverheadTextOn(Player player, String text)
	{
		if (player == null || text == null || text.trim().isEmpty())
		{
			return;
		}

		player.setOverheadText(text.trim());
		player.setOverheadCycle(OVERHEAD_CYCLES);
	}

	/** Returns the caster from an ally cast message, or null if the wording no longer matches. */
	private static String casterFrom(String rawMessage)
	{
		final String plain = Text.removeTags(rawMessage);
		final int end = plain.toLowerCase().indexOf(ALLY_CAST_NAME_SUFFIX);
		if (end <= 0)
		{
			return null;
		}

		final String name = plainName(plain.substring(0, end));
		return name.isEmpty() ? null : name;
	}

	/** Plays the sound for a buff going to waste, unless another fade from the same blow already has. */
	private void playExpiry(String bundled, String customStem)
	{
		if (expirySoundPlayed)
		{
			return;
		}

		expirySoundPlayed = true;
		play(bundled, customStem);
	}

	private void play(String bundled, String customStem)
	{
		final int volume = config.volume();
		if (!config.enableSounds() || volume <= 0)
		{
			return;
		}

		final float gain = 20f * (float) Math.log10(volume / 100f);
		final File override = config.useCustomSounds() ? pickOverride(stemFor(bundled, customStem)) : null;

		try
		{
			if (override != null)
			{
				audioPlayer.play(override, gain);
			}
			else
			{
				audioPlayer.play(getClass(), BUNDLED_SOUND_PATH + bundled + WAV, gain);
			}
		}
		// AudioPlayer declares checked exceptions from the sound API, which the plugin hub does not
		// allow us to name. Catching Exception covers them without importing them, and a failed sound
		// is only ever logged either way.
		catch (Exception e)
		{
			log.warn("Failed to play {}", override != null ? override : bundled, e);
		}
	}

	private static String stemFor(String bundled, String customStem)
	{
		if (customStem == null)
		{
			return bundled;
		}

		final String unquoted = unquote(customStem);
		return unquoted.isEmpty() ? bundled : unquoted;
	}

	/**
	 * Windows' Copy as path wraps a path in double quotes, and people type single ones too, so any
	 * quotes around the setting are dropped.
	 */
	static String unquote(String setting)
	{
		String value = setting.trim();
		while (!value.isEmpty() && isQuote(value.charAt(0)))
		{
			value = value.substring(1).trim();
		}
		while (!value.isEmpty() && isQuote(value.charAt(value.length() - 1)))
		{
			value = value.substring(0, value.length() - 1).trim();
		}
		return value;
	}

	private static boolean isQuote(char c)
	{
		return c == '"' || c == '\'';
	}

	/**
	 * Resolves the user's clip for an event, or null to fall back to the bundled sound. Accepts a
	 * full path to a .wav, a full path to a folder to pick from, or a bare name looked up in the
	 * plugin's own sound folder.
	 */
	private static File pickOverride(String setting)
	{
		return pickOverride(SOUND_DIR, setting);
	}

	/** Takes the folder explicitly so the resolution can be exercised against a real directory. */
	static File pickOverride(File soundDir, String setting)
	{
		final File asPath = new File(setting);
		if (asPath.isAbsolute())
		{
			if (asPath.isDirectory())
			{
				return randomWavIn(asPath, null);
			}

			if (!asPath.isFile())
			{
				return null;
			}

			if (!isSupportedAudio(asPath.getName().toLowerCase()))
			{
				log.warn("{} is not a format java.sound can play; convert it to .wav", asPath);
				return null;
			}

			return asPath;
		}

		return randomWavIn(soundDir, setting);
	}

	private static boolean isSupportedAudio(String lowerName)
	{
		for (String extension : AUDIO_EXTENSIONS)
		{
			if (lowerName.endsWith(extension))
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Picks a random .wav from a folder. With a stem, both {@code name.wav} and any {@code name-*.wav}
	 * qualify, so dropping in several variants gives a different one each time.
	 */
	private static File randomWavIn(File directory, String stem)
	{
		final String wanted = stem == null ? null : stem.toLowerCase();

		final File[] candidates = directory.listFiles((dir, name) ->
		{
			final String lower = name.toLowerCase();
			if (!isSupportedAudio(lower))
			{
				return false;
			}

			if (wanted == null || lower.startsWith(wanted + "-"))
			{
				return true;
			}

			return lower.substring(0, lower.lastIndexOf('.')).equals(wanted);
		});

		if (candidates == null || candidates.length == 0)
		{
			return null;
		}

		return candidates[ThreadLocalRandom.current().nextInt(candidates.length)];
	}
}

package soulflameaudio;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/** Counts down the seconds left on the Entice buff, next to the horn's own icon. */
class SoulflameHornInfoBox extends InfoBox
{
	private final SoulflameHornAudioPlugin plugin;

	SoulflameHornInfoBox(BufferedImage image, Plugin owner, SoulflameHornAudioPlugin plugin)
	{
		super(image, owner);
		this.plugin = plugin;
	}

	@Override
	public String getText()
	{
		return plugin.getEnticeCountdown();
	}

	/** Warns on the real remaining time, so the colour does not change with the chosen unit. */
	@Override
	public Color getTextColor()
	{
		return plugin.getEnticeSecondsRemaining() <= 2 ? Color.RED : Color.WHITE;
	}

	@Override
	public boolean render()
	{
		return plugin.isInfoBoxEnabled() && plugin.isEnticeActive();
	}

	@Override
	public String getTooltip()
	{
		return "Entice: next melee attack is guaranteed to hit";
	}
}

package soulflameaudio;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Outlines the ground your horn would reach, so you can see who is inside it before blowing it, and
 * that of each party member wearing one, from the radius they shared.
 */
class SoulflameHornRadiusOverlay extends Overlay
{
	private final Client client;
	private final SoulflameHornAudioPlugin plugin;
	private final SoulflameHornAudioConfig config;

	@Inject
	SoulflameHornRadiusOverlay(Client client, SoulflameHornAudioPlugin plugin, SoulflameHornAudioConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Player localPlayer = client.getLocalPlayer();
		if (config.showHornRadius() && localPlayer != null && plugin.isHornEquipped())
		{
			draw(graphics, localPlayer, plugin.getHornRadius(), config.radiusColour());
		}

		if (config.partyIntegration() && config.showPartyRadius())
		{
			plugin.partyHornRadii().forEach((member, radius) -> draw(graphics, member, radius, config.partyRadiusColour()));
		}

		return null;
	}

	private void draw(Graphics2D graphics, Player player, int radius, Color outline)
	{
		if (radius <= 0)
		{
			return;
		}

		final Area area = reachableArea(player.getWorldLocation(), radius);
		if (area == null || area.isEmpty())
		{
			return;
		}

		OverlayUtil.renderPolygon(graphics, area, outline, fill(outline, config.radiusFillOpacity()),
			new BasicStroke((float) config.radiusBorderWidth()));
	}

	/** The outline's colour at a share of its opacity, so the two fade together. */
	static Color fill(Color outline, int fillPercent)
	{
		return new Color(outline.getRed(), outline.getGreen(), outline.getBlue(), outline.getAlpha() * fillPercent / 100);
	}

	/**
	 * Unions the tiles individually rather than projecting one big square. Each tile is drawn at its
	 * own terrain height, so the shape stays true across stairs and slopes instead of skewing between
	 * four corners at wildly different heights.
	 */
	private Area reachableArea(WorldPoint centre, int radius)
	{
		if (centre == null)
		{
			return null;
		}

		final WorldView worldView = client.getTopLevelWorldView();
		final Area area = new Area();

		for (int dx = -radius; dx <= radius; dx++)
		{
			for (int dy = -radius; dy <= radius; dy++)
			{
				final LocalPoint tile = LocalPoint.fromWorld(worldView, centre.dx(dx).dy(dy));
				if (tile == null)
				{
					continue;
				}

				final Polygon poly = Perspective.getCanvasTilePoly(client, tile);
				if (poly != null)
				{
					area.add(new Area(poly));
				}
			}
		}

		return area;
	}
}

package soulflameaudio;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Says why the radius outline is missing. The horn reports no radius until it has been configured,
 * and the configure option only appears while it is equipped, so without this the overlay would
 * simply draw nothing and leave no clue as to why.
 */
class SoulflameHornReminderOverlay extends OverlayPanel
{
	private static final Color BACKGROUND = new Color(120, 20, 20, 110);
	private static final Color TEXT = new Color(255, 225, 225);
	private static final String MESSAGE = "Right-click your horn to set its radius";

	private final SoulflameHornAudioPlugin plugin;
	private final SoulflameHornAudioConfig config;

	@Inject
	SoulflameHornReminderOverlay(SoulflameHornAudioPlugin plugin, SoulflameHornAudioConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setBackgroundColor(BACKGROUND);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showHornRadius() || !plugin.isHornEquipped() || plugin.isHornRadiusConfigured())
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(MESSAGE)
			.color(TEXT)
			.build());

		return super.render(graphics);
	}
}

package soulflameaudio;

import java.io.BufferedInputStream;
import java.io.InputStream;
import javax.sound.sampled.AudioInputStream;
import javax.sound.sampled.AudioSystem;
import org.junit.Test;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * The bundled sounds are looked up by classpath path at runtime, so a resource that moved or failed
 * to decode would only surface as silence in game.
 */
public class BundledSoundsTest
{
	@Test
	public void appliedSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.APPLIED_SOUND);
	}

	@Test
	public void consumedSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.CONSUMED_SOUND);
	}

	@Test
	public void whiffSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.WHIFF_SOUND);
	}

	@Test
	public void fadedSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.FADED_SOUND);
	}

	@Test
	public void allyWastedSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.ALLY_WASTED_SOUND);
	}

	@Test
	public void sentSoundIsBundledAndDecodable() throws Exception
	{
		assertDecodable(SoulflameHornAudioPlugin.SENT_SOUND);
	}

	private static void assertDecodable(String stem) throws Exception
	{
		String path = "/soulflameaudio/" + stem + ".wav";
		InputStream resource = SoulflameHornAudioPlugin.class.getResourceAsStream(path);
		assertNotNull("missing bundled resource " + path, resource);

		try (AudioInputStream audio = AudioSystem.getAudioInputStream(new BufferedInputStream(resource)))
		{
			assertTrue("empty audio stream " + path, audio.getFrameLength() > 0);
		}
	}
}

package soulflameaudio;

import java.io.File;
import java.io.IOException;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** Exercises custom audio resolution against real files, rather than a mocked filesystem. */
public class CustomAudioResolutionTest
{
	@Rule
	public final TemporaryFolder soundFolder = new TemporaryFolder();

	@Test
	public void anExactlyNamedFileIsFound() throws IOException
	{
		File wav = soundFolder.newFile("entice-sent.wav");

		assertEquals(wav, SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent"));
	}

	@Test
	public void anEmptyFolderResolvesToNothing()
	{
		assertNull("with no files the bundled sound must be used",
			SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent"));
	}

	@Test
	public void suffixedVariantsAreAllCandidates() throws IOException
	{
		soundFolder.newFile("entice-sent-one.wav");
		soundFolder.newFile("entice-sent-two.wav");

		for (int i = 0; i < 20; i++)
		{
			File picked = SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent");
			assertNotNull(picked);
			assertTrue(picked.getName(), picked.getName().startsWith("entice-sent-"));
		}
	}

	@Test
	public void aDifferentEventsFileIsNotPickedUp() throws IOException
	{
		soundFolder.newFile("entice-whiff.wav");

		assertNull(SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent"));
	}

	@Test
	public void aCustomNameIsMatchedAsGiven() throws IOException
	{
		File wav = soundFolder.newFile("yeah-baby.wav");

		assertEquals(wav, SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "yeah-baby"));
	}

	@Test
	public void matchingIgnoresCase() throws IOException
	{
		File wav = soundFolder.newFile("Entice-Sent.WAV");

		assertEquals(wav, SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent"));
	}

	@Test
	public void anUnplayableFormatIsIgnored() throws IOException
	{
		soundFolder.newFile("entice-sent.mp3");

		assertNull("mp3 cannot be decoded, so it must fall back rather than fail",
			SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), "entice-sent"));
	}

	@Test
	public void anAbsolutePathToAFileIsUsedDirectly() throws IOException
	{
		File wav = soundFolder.newFile("anywhere.wav");

		assertEquals(wav, SoulflameHornAudioPlugin.pickOverride(soundFolder.getRoot(), wav.getAbsolutePath()));
	}

	@Test
	public void anAbsolutePathToAFolderPicksFromIt() throws IOException
	{
		File wav = soundFolder.newFile("whatever-name.wav");

		assertEquals(wav, SoulflameHornAudioPlugin.pickOverride(
			soundFolder.getRoot(), soundFolder.getRoot().getAbsolutePath()));
	}
}

